import { readFileSync } from "node:fs";
import { dirname, resolve as resolvePath } from "node:path";
import { fileURLToPath } from "node:url";
import type { CaveBuildLock, CavePlan } from "./build.js";
import { sha256, stableStringify, type ContextIR } from "./context-ir.js";
import {
  prepareLockedHarnessExecution,
  validateProviderUsage,
} from "./execution-kernel.js";

export type HarnessID = "pi" | "claude" | "vercel-ai-sdk" | "eve" | "mastra";

export const VERCEL_AI_SDK_VERSION = "7.0.43";
export const EVE_VERSION = "0.29.2";
export const MASTRA_VERSION = "1.55.0";

export interface HarnessRequest {
  build: CaveBuildLock;
  contextIR: ContextIR;
  plan: CavePlan;
  prompt: string;
  runID: string;
  evaluatedTransformIDs: string[];
  appliedTransformIDs: string[];
  recoveryResolved: boolean;
  signal?: AbortSignal;
}

export interface HarnessExecution {
  terminal: boolean;
  text: string;
  provider: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  totalTokens: number;
  costUsd: number;
  usageBasis: "provider_reported" | "missing";
  priceBasis: "public_catalog" | "unpriced";
  evaluatedTransformIDs: string[];
  appliedTransformIDs: string[];
  recoveryResolved: boolean;
  latencyMs: number;
}

export interface HarnessResult extends HarnessExecution {
  harness: HarnessID;
  adapterBuildSHA256: string;
  adapterContractSHA256: string;
  sourceBuildSHA256: string;
  planSHA256: string;
  contextIRSHA256: string;
  claimBasis: "inferred";
  verifiedSavingsUsd: 0;
}

export interface HarnessAdapter {
  readonly id: HarnessID;
  readonly version: string;
  readonly manifest: HarnessAdapterManifest;
  readonly contractSHA256: string;
  run(request: HarnessRequest): Promise<HarnessResult>;
}

export type HarnessInvoke = (request: Readonly<HarnessRequest>) => Promise<HarnessExecution>;

export interface HarnessAdapterIdentity {
  adapterVersion: string;
  upstreamVersion: string;
  bundleSHA256: string;
  dependencyLockSHA256: string;
}

export interface HarnessAdapterManifest extends HarnessAdapterIdentity {
  schemaVersion: 1;
  harness: HarnessID;
  wireContract: Readonly<Record<string, unknown>>;
}

export function createHarnessAdapter(
  id: HarnessID,
  identity: HarnessAdapterIdentity,
  wireContract: Readonly<Record<string, unknown>>,
  invoke: HarnessInvoke,
): HarnessAdapter {
  if (!/^[0-9A-Za-z][0-9A-Za-z._-]{0,63}$/.test(identity.adapterVersion)) {
    throw new Error("cave_harness_adapter_version_invalid");
  }
  if (!/^[0-9A-Za-z][0-9A-Za-z._+-]{0,127}$/.test(identity.upstreamVersion)) {
    throw new Error("cave_harness_upstream_version_invalid");
  }
  if (!/^[0-9a-f]{64}$/.test(identity.bundleSHA256) ||
      !/^[0-9a-f]{64}$/.test(identity.dependencyLockSHA256)) {
    throw new Error("cave_harness_artifact_digest_invalid");
  }
  const manifest = deepFreeze({
    schemaVersion: 1 as const,
    harness: id,
    adapterVersion: identity.adapterVersion,
    upstreamVersion: identity.upstreamVersion,
    bundleSHA256: identity.bundleSHA256,
    dependencyLockSHA256: identity.dependencyLockSHA256,
    wireContract: canonicalRecord(wireContract),
  });
  const contractSHA256 = sha256(stableStringify(manifest));
  return Object.freeze({
    id,
    version: identity.adapterVersion,
    manifest,
    contractSHA256,
    async run(request: HarnessRequest): Promise<HarnessResult> {
      const frozenRequest = snapshotRequest(request);
      const prepared = prepareLockedHarnessExecution({
        build: frozenRequest.build,
        harness: id,
        adapterVersion: identity.adapterVersion,
        upstreamVersion: identity.upstreamVersion,
        contextIR: frozenRequest.contextIR,
        plan: frozenRequest.plan,
      });
      const { build, planSHA256, contextIRSHA256 } = prepared;
      if (typeof frozenRequest.prompt !== "string" || frozenRequest.prompt.length === 0 ||
          typeof frozenRequest.runID !== "string" || frozenRequest.runID.length === 0) {
        throw new Error("cave_harness_request_invalid");
      }
      if (isAborted(frozenRequest.signal)) throw new Error("cave_harness_aborted");
      validateTransformEvidence(frozenRequest, frozenRequest.plan);
      const execution = snapshotExecution(await invoke(frozenRequest));
      if (isAborted(frozenRequest.signal)) throw new Error("cave_harness_aborted");
      validateExecution(execution, frozenRequest.plan);
      return {
        terminal: execution.terminal,
        text: execution.text,
        provider: execution.provider,
        model: execution.model,
        inputTokens: execution.inputTokens,
        outputTokens: execution.outputTokens,
        cacheReadTokens: execution.cacheReadTokens,
        cacheWriteTokens: execution.cacheWriteTokens,
        reasoningTokens: execution.reasoningTokens,
        totalTokens: execution.totalTokens,
        costUsd: execution.costUsd,
        usageBasis: execution.usageBasis,
        priceBasis: execution.priceBasis,
        evaluatedTransformIDs: [...execution.evaluatedTransformIDs],
        appliedTransformIDs: [...execution.appliedTransformIDs],
        recoveryResolved: execution.recoveryResolved,
        latencyMs: execution.latencyMs,
        harness: id,
        adapterBuildSHA256: sha256(stableStringify({
          harness: id,
          version: identity.adapterVersion,
          contractSHA256,
          sourceBuildSHA256: build.build_sha256,
        })),
        adapterContractSHA256: contractSHA256,
        sourceBuildSHA256: build.build_sha256,
        planSHA256,
        contextIRSHA256,
        claimBasis: "inferred",
        verifiedSavingsUsd: 0,
      };
    },
  });
}

export const createPiAdapter = (identity: HarnessAdapterIdentity, invoke: HarnessInvoke) =>
  createHarnessAdapter("pi", identity, {
    kind: "caveman-pi",
    version: 1,
    request: "HarnessRequest.v1",
    response: "HarnessExecution.v1",
  }, invoke);

export const createClaudeAdapter = (identity: HarnessAdapterIdentity, invoke: HarnessInvoke) =>
  createHarnessAdapter("claude", identity, {
    kind: "caveman-claude",
    version: 1,
    request: "HarnessRequest.v1",
    response: "HarnessExecution.v1",
  }, invoke);

export interface VercelToolLoopAgentBinding {
  generate(options: { prompt: string; abortSignal?: AbortSignal }): PromiseLike<{
    text: string;
    usage: unknown;
    finishReason?: unknown;
    error?: unknown;
    response?: { modelId?: unknown };
  }>;
}

export function createVercelAISDKAdapter(
  identity: HarnessAdapterIdentity,
  agent: VercelToolLoopAgentBinding,
): HarnessAdapter {
  assertSupportedUpstream(identity, VERCEL_AI_SDK_VERSION, "vercel", "ai");
  return createHarnessAdapter("vercel-ai-sdk", identity, {
    package: "ai",
    class: "ToolLoopAgent",
    method: "generate",
    usage: "LanguageModelUsage.v4",
  }, async (request) => {
    const startedAt = performance.now();
    const response = await agent.generate({
      prompt: request.prompt,
      ...(request.signal === undefined ? {} : { abortSignal: request.signal }),
    });
    if (response.error !== undefined || terminalFinishReason(response.finishReason) === false) {
      throw new Error("cave_vercel_terminal_failure");
    }
    const expected = expectedProviderModel(request.plan);
    const actualModel = normalizedResponseModel(response.response?.modelId, expected.provider);
    return harnessExecution({
      request,
      text: response.text,
      provider: expected.provider,
      model: actualModel,
      usage: usageFromAISDK(response.usage, request.plan.reasoning !== "none"),
      latencyMs: Math.round(performance.now() - startedAt),
    });
  });
}

export interface EveMessageResponseBinding {
  result(): Promise<{
    message: string | undefined;
    status: "completed" | "failed" | "waiting";
    events: unknown[];
  }>;
}

export interface EveSessionBinding {
  send(input: { message: string; signal?: AbortSignal }): Promise<EveMessageResponseBinding>;
}

export function createEveAdapter(
  identity: HarnessAdapterIdentity,
  session: EveSessionBinding,
): HarnessAdapter {
  assertSupportedUpstream(identity, EVE_VERSION, "eve", "eve");
  return createHarnessAdapter("eve", identity, {
    package: "eve/client",
    class: "ClientSession",
    method: "send.result",
    usage: "step.completed.data.usage",
  }, async (request) => {
    const startedAt = performance.now();
    const response = await session.send({
      message: request.prompt,
      ...(request.signal === undefined ? {} : { signal: request.signal }),
    });
    const result = await response.result();
    if (result.status !== "completed") throw new Error(`cave_eve_terminal_${result.status}`);
    const identity = eveRuntimeIdentity(result.events);
    if (identity.upstreamVersion !== request.build.harness.upstream_version) {
      throw new Error("cave_harness_upstream_version_mismatch");
    }
    const usage = usageFromEveEvents(result.events, request.plan.reasoning !== "none");
    return harnessExecution({
      request,
      text: result.message ?? "",
      provider: identity.provider,
      model: identity.model,
      usage,
      latencyMs: Math.round(performance.now() - startedAt),
    });
  });
}

export interface MastraAgentBinding {
  generate(messages: string, options?: {
    maxProcessorRetries?: number;
    maxSteps?: number;
    runId?: string;
    abortSignal?: AbortSignal;
  }): Promise<{
    text: string;
    totalUsage?: unknown;
    usage?: unknown;
    error?: unknown;
    finishReason?: unknown;
    response?: { modelId?: unknown };
  }>;
}

export interface MastraAdapterOptions {
  /** Mastra's per-generate maximum number of sequential LLM calls. */
  maxSteps?: number;
}

export function createMastraAdapter(
  identity: HarnessAdapterIdentity,
  agent: MastraAgentBinding,
  options: MastraAdapterOptions = {},
): HarnessAdapter {
  const maxSteps = options.maxSteps;
  if (maxSteps !== undefined && (!Number.isSafeInteger(maxSteps) || maxSteps <= 0)) {
    throw new Error("cave_mastra_max_steps_invalid");
  }
  assertSupportedUpstream(identity, MASTRA_VERSION, "mastra", "@mastra/core");
  return createHarnessAdapter("mastra", identity, {
    package: "@mastra/core/agent",
    class: "Agent",
    method: "generate",
    usage: "FullOutput.totalUsage",
    ...(maxSteps === undefined ? {} : { preExecutionControls: { maxSteps } }),
  }, async (request) => {
    const startedAt = performance.now();
    const response = await agent.generate(request.prompt, {
      maxProcessorRetries: 0,
      runId: request.runID,
      ...(maxSteps === undefined ? {} : { maxSteps }),
      ...(request.signal === undefined ? {} : { abortSignal: request.signal }),
    });
    if (response.error !== undefined || terminalFinishReason(response.finishReason) === false) {
      throw new Error("cave_mastra_terminal_failure");
    }
    const expected = expectedProviderModel(request.plan);
    const actualModel = normalizedResponseModel(response.response?.modelId, expected.provider);
    return harnessExecution({
      request,
      text: response.text,
      provider: expected.provider,
      model: actualModel,
      usage: usageFromMastra(response.totalUsage ?? response.usage, request.plan.reasoning !== "none"),
      latencyMs: Math.round(performance.now() - startedAt),
    });
  });
}

interface NormalizedUsage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  totalTokens: number;
}

function harnessExecution(input: {
  request: Readonly<HarnessRequest>;
  text: string;
  provider: string;
  model: string;
  usage: NormalizedUsage;
  latencyMs: number;
}): HarnessExecution {
  const expected = expectedProviderModel(input.request.plan);
  if (input.provider !== expected.provider || input.model !== expected.model) {
    throw new Error("cave_harness_incomplete_evidence");
  }
  const priced = validateProviderUsage({
    provider: input.provider,
    model: input.model,
    ...input.usage,
  }, { requirePriced: true });
  return {
    terminal: true,
    text: input.text,
    provider: input.provider,
    model: input.model,
    ...input.usage,
    costUsd: priced.catalogCostUsd,
    usageBasis: "provider_reported",
    priceBasis: "public_catalog",
    evaluatedTransformIDs: [...input.request.evaluatedTransformIDs],
    appliedTransformIDs: [...input.request.appliedTransformIDs],
    recoveryResolved: input.request.recoveryResolved,
    latencyMs: input.latencyMs,
  };
}

function usageFromAISDK(value: unknown, reasoningRequired: boolean): NormalizedUsage {
  const usage = record(value, "cave_vercel_usage_missing");
  const input = record(usage.inputTokenDetails, "cave_vercel_usage_missing");
  const output = record(usage.outputTokenDetails, "cave_vercel_usage_missing");
  const totalInput = strictInteger(usage.inputTokens, "cave_vercel_usage_missing");
  const cacheRead = optionalInteger(input.cacheReadTokens, "cave_vercel_usage_missing");
  const cacheWrite = optionalInteger(input.cacheWriteTokens, "cave_vercel_usage_missing");
  if (cacheRead + cacheWrite > totalInput) throw new Error("cave_vercel_usage_missing");
  const noCache = input.noCacheTokens === undefined
    ? totalInput - cacheRead - cacheWrite
    : strictInteger(input.noCacheTokens, "cave_vercel_usage_missing");
  if (noCache + cacheRead + cacheWrite !== totalInput) {
    throw new Error("cave_vercel_usage_missing");
  }
  const normalized = normalizeUsage({
    inputTokens: noCache,
    outputTokens: usage.outputTokens,
    cacheReadTokens: cacheRead,
    cacheWriteTokens: cacheWrite,
    reasoningTokens: output.reasoningTokens,
    totalTokens: usage.totalTokens,
  }, reasoningRequired, "cave_vercel_usage_missing");
  return normalized;
}

function usageFromMastra(value: unknown, reasoningRequired: boolean): NormalizedUsage {
  const usage = record(value, "cave_mastra_usage_missing");
  const totalInput = strictInteger(usage.inputTokens, "cave_mastra_usage_missing");
  const cacheRead = optionalInteger(usage.cachedInputTokens, "cave_mastra_usage_missing");
  const cacheWrite = optionalInteger(usage.cacheCreationInputTokens, "cave_mastra_usage_missing");
  if (cacheRead + cacheWrite > totalInput) throw new Error("cave_mastra_usage_missing");
  return normalizeUsage({
    inputTokens: totalInput - cacheRead - cacheWrite,
    outputTokens: usage.outputTokens,
    cacheReadTokens: cacheRead,
    cacheWriteTokens: cacheWrite,
    reasoningTokens: usage.reasoningTokens,
    totalTokens: usage.totalTokens,
  }, reasoningRequired, "cave_mastra_usage_missing");
}

function usageFromEveEvents(events: unknown[], reasoningRequired: boolean): NormalizedUsage {
  let totalInputTokens = 0;
  let outputTokens = 0;
  let cacheReadTokens = 0;
  let cacheWriteTokens = 0;
  let steps = 0;
  for (const event of events) {
    if (!isRecord(event) || event.type !== "step.completed" || !isRecord(event.data)) continue;
    const usage = record(event.data.usage, "cave_eve_usage_missing");
    totalInputTokens += strictInteger(usage.inputTokens, "cave_eve_usage_missing");
    outputTokens += strictInteger(usage.outputTokens, "cave_eve_usage_missing");
    cacheReadTokens += strictInteger(usage.cacheReadTokens, "cave_eve_usage_missing");
    cacheWriteTokens += strictInteger(usage.cacheWriteTokens, "cave_eve_usage_missing");
    steps++;
  }
  if (steps === 0 || reasoningRequired) throw new Error("cave_eve_usage_missing");
  if (cacheReadTokens + cacheWriteTokens > totalInputTokens) {
    throw new Error("cave_eve_usage_missing");
  }
  const inputTokens = totalInputTokens - cacheReadTokens - cacheWriteTokens;
  return normalizeUsage({
    inputTokens,
    outputTokens,
    cacheReadTokens,
    cacheWriteTokens,
    reasoningTokens: 0,
    totalTokens: inputTokens + outputTokens + cacheReadTokens + cacheWriteTokens,
  }, false, "cave_eve_usage_missing");
}

function normalizeUsage(
  value: Record<keyof NormalizedUsage, unknown>,
  reasoningRequired: boolean,
  error: string,
): NormalizedUsage {
  const reasoningTokens = reasoningRequired
    ? strictInteger(value.reasoningTokens, error)
    : optionalInteger(value.reasoningTokens, error);
  const usage = {
    inputTokens: strictInteger(value.inputTokens, error),
    outputTokens: strictInteger(value.outputTokens, error),
    cacheReadTokens: strictInteger(value.cacheReadTokens, error),
    cacheWriteTokens: strictInteger(value.cacheWriteTokens, error),
    reasoningTokens,
    totalTokens: strictInteger(value.totalTokens, error),
  };
  if (usage.totalTokens !== usage.inputTokens + usage.outputTokens +
      usage.cacheReadTokens + usage.cacheWriteTokens ||
      usage.reasoningTokens > usage.outputTokens) {
    throw new Error(error);
  }
  return usage;
}

function eveRuntimeIdentity(events: unknown[]): {
  provider: string;
  model: string;
  upstreamVersion: string;
} {
  const starts = events.filter((event) =>
    isRecord(event) && event.type === "session.started" && isRecord(event.data) &&
    isRecord(event.data.runtime));
  if (starts.length !== 1) throw new Error("cave_eve_runtime_identity_missing");
  const runtime = (starts[0] as { data: { runtime: Record<string, unknown> } }).data.runtime;
  if (typeof runtime.modelId !== "string" || runtime.modelId.length === 0 ||
      runtime.modelId.startsWith("dynamic:")) {
    throw new Error("cave_eve_runtime_identity_missing");
  }
  const separator = runtime.modelId.indexOf("/");
  if (separator < 1 || separator === runtime.modelId.length - 1 ||
      typeof runtime.eveVersion !== "string" || runtime.eveVersion.length === 0) {
    throw new Error("cave_eve_runtime_identity_missing");
  }
  return {
    provider: runtime.modelId.slice(0, separator),
    model: runtime.modelId.slice(separator + 1),
    upstreamVersion: runtime.eveVersion,
  };
}

function expectedProviderModel(plan: CavePlan): { provider: string; model: string } {
  const separator = plan.model.indexOf("/");
  if (separator < 1 || separator === plan.model.length - 1) {
    throw new Error("cave_harness_model_invalid");
  }
  return { provider: plan.model.slice(0, separator), model: plan.model.slice(separator + 1) };
}

function normalizedResponseModel(value: unknown, provider: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new Error("cave_harness_model_identity_missing");
  }
  return value.startsWith(`${provider}/`) ? value.slice(provider.length + 1) : value;
}

function terminalFinishReason(value: unknown): boolean {
  return typeof value === "string" && ["stop", "length", "content-filter", "other"].includes(value);
}

function record(value: unknown, error: string): Record<string, unknown> {
  if (!isRecord(value)) throw new Error(error);
  return value;
}

function strictInteger(value: unknown, error: string): number {
  if (!Number.isSafeInteger(value) || Number(value) < 0) throw new Error(error);
  return Number(value);
}

function optionalInteger(value: unknown, error: string): number {
  return value === undefined ? 0 : strictInteger(value, error);
}

function isAborted(signal: AbortSignal | undefined): boolean {
  return signal?.aborted === true;
}

/**
 * Read the ACTUALLY-INSTALLED version of a package from its own package.json
 * `import.meta.resolve` is synchronous in Node and locates the
 * real resolved module, so the identity is derived from what is installed — not
 * from a caller-supplied string that could claim a supported version while a
 * different one runs.
 */
function installedPackageVersion(pkg: string): string | undefined {
  const readVersion = (jsonPath: string, requireName: boolean): string | undefined => {
    try {
      const json = JSON.parse(readFileSync(jsonPath, "utf8")) as { name?: unknown; version?: unknown };
      if (requireName && json.name !== pkg) return undefined;
      return typeof json.version === "string" ? json.version : undefined;
    } catch {
      return undefined;
    }
  };
  // Preferred: the package exposes its own package.json (most modern packages).
  try {
    const direct = readVersion(fileURLToPath(import.meta.resolve(`${pkg}/package.json`)), false);
    if (direct !== undefined) return direct;
  } catch {
    // exports map may not expose package.json; fall through to walking up.
  }
  // Fallback: resolve the package entry and walk up to its package.json.
  try {
    let dir = dirname(fileURLToPath(import.meta.resolve(pkg)));
    for (let depth = 0; depth < 12; depth += 1) {
      const version = readVersion(resolvePath(dir, "package.json"), true);
      if (version !== undefined) return version;
      const parent = dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  } catch {
    // Not resolvable at all.
  }
  return undefined;
}

function assertSupportedUpstream(
  identity: HarnessAdapterIdentity,
  expected: string,
  harness: string,
  pkg: string,
): void {
  // The pin is enforced against the INSTALLED version, and the caller's claimed
  // upstreamVersion must match what is actually installed — a claim alone can no
  // longer authorize execution.
  const installed = installedPackageVersion(pkg);
  if (installed === undefined) {
    throw new Error(`cave_${harness}_upstream_version_unresolvable`);
  }
  if (installed !== expected) {
    throw new Error(`cave_${harness}_upstream_version_unsupported`);
  }
  if (identity.upstreamVersion !== installed) {
    throw new Error(`cave_${harness}_upstream_version_mismatch`);
  }
}

function canonicalRecord(value: Readonly<Record<string, unknown>>): Readonly<Record<string, unknown>> {
  let encoded: string;
  try {
    encoded = stableStringify(value);
  } catch {
    throw new Error("cave_harness_wire_contract_invalid");
  }
  const decoded = JSON.parse(encoded) as unknown;
  if (!isRecord(decoded)) throw new Error("cave_harness_wire_contract_invalid");
  return decoded;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object") {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function snapshotRequest(request: HarnessRequest): Readonly<HarnessRequest> {
  try {
    const { signal, ...serializable } = request;
    const snapshot = deepFreeze(structuredClone(serializable));
    if (signal === undefined) return snapshot;
    if (typeof signal.aborted !== "boolean" || typeof signal.addEventListener !== "function") {
      throw new Error("cave_harness_signal_invalid");
    }
    return Object.freeze({ ...snapshot, signal });
  } catch {
    throw new Error("cave_harness_request_invalid");
  }
}

function snapshotExecution(value: HarnessExecution): Readonly<HarnessExecution> {
  if (!isRecord(value) ||
      !Array.isArray(value.evaluatedTransformIDs) ||
      !Array.isArray(value.appliedTransformIDs)) {
    throw new Error("cave_harness_incomplete_evidence");
  }
  return deepFreeze({
    terminal: value.terminal,
    text: value.text,
    provider: value.provider,
    model: value.model,
    inputTokens: value.inputTokens,
    outputTokens: value.outputTokens,
    cacheReadTokens: value.cacheReadTokens,
    cacheWriteTokens: value.cacheWriteTokens,
    reasoningTokens: value.reasoningTokens,
    totalTokens: value.totalTokens,
    costUsd: value.costUsd,
    usageBasis: value.usageBasis,
    priceBasis: value.priceBasis,
    evaluatedTransformIDs: [...value.evaluatedTransformIDs],
    appliedTransformIDs: [...value.appliedTransformIDs],
    recoveryResolved: value.recoveryResolved,
    latencyMs: value.latencyMs,
  });
}

function validateTransformEvidence(
  evidence: Pick<HarnessRequest, "evaluatedTransformIDs" | "appliedTransformIDs" | "recoveryResolved">,
  plan: CavePlan,
): void {
  if (!Array.isArray(evidence.evaluatedTransformIDs) ||
      !Array.isArray(evidence.appliedTransformIDs) ||
      evidence.evaluatedTransformIDs.some((value) => typeof value !== "string" || value.length === 0) ||
      evidence.appliedTransformIDs.some((value) => typeof value !== "string" || value.length === 0) ||
      evidence.recoveryResolved !== true) {
    throw new Error("cave_harness_incomplete_evidence");
  }
  const selected = [...new Set(plan.segment_routes.map((route) => route.transform_id))].sort();
  const evaluated = [...new Set(evidence.evaluatedTransformIDs)].sort();
  const applied = [...new Set(evidence.appliedTransformIDs)].sort();
  if (selected.some((transformID) => !evaluated.includes(transformID))) {
    throw new Error("cave_harness_transform_not_evaluated");
  }
  if (evaluated.some((transformID) => !selected.includes(transformID)) ||
      applied.some((transformID) => !selected.includes(transformID))) {
    throw new Error("cave_harness_unknown_transform");
  }
}

function validateExecution(execution: HarnessExecution, plan: CavePlan): void {
  const [provider, ...modelParts] = plan.model.split("/");
  const model = modelParts.join("/");
  try {
    validateProviderUsage(execution, {
      expected: { provider: provider ?? "", model },
      reportedCostUsd: execution.costUsd,
      requirePriced: true,
    });
  } catch {
    throw new Error("cave_harness_incomplete_evidence");
  }
  if (execution.terminal !== true || typeof execution.text !== "string" ||
      execution.text.length === 0 ||
      execution.usageBasis !== "provider_reported" ||
      execution.priceBasis !== "public_catalog" ||
      !Number.isFinite(execution.latencyMs) || execution.latencyMs < 0 ||
      execution.recoveryResolved !== true) {
    throw new Error("cave_harness_incomplete_evidence");
  }
  validateTransformEvidence(execution, plan);
}

import { sha256, stableStringify } from "./context-ir.js";

/**
 * Deterministic circuit breakers.
 *
 * Every decision in this file is a hash comparison or an integer count. No
 * model runs anywhere in the breaker path: a model judge cannot participate in
 * stopping or accounting, so all breaker decisions stay deterministic.
 *
 * Local enforcement shares the worker detector's H6 repeat edge: same tool +
 * normalized arguments, excluding a repeat whose immediately-preceding
 * attempt failed. Exact repeats expire after a bounded turn window, so old
 * successful work cannot poison the rest of a long run. Worker-side finding
 * arithmetic is intentionally broader: session graph SCCs plus a population
 * Isolation-Forest confirmation. Local runtime has neither full-session
 * population nor authority to mint findings.
 */
export interface RunBreakers {
  /**
   * How many identical tool calls — same tool, same normalized arguments — end
   * the run. Counted per hash, reset by an intervening failure. Defaults to 3.
   */
  readonly repeatedToolCalls?: number;
  /**
   * Assistant-turn window in which identical calls count toward
   * `repeatedToolCalls`. Older calls decay out. Defaults to 8.
   */
  readonly repeatedToolCallWindowTurns?: number;
  /**
   * How many consecutive read-only turns with an identical outcome signature
   * (same model conclusion and tool identities/results) end the run. Successful
   * declared writes reset the window because equal display text is not proof
   * that host state stayed equal. Defaults to 3.
   */
  readonly noProgressTurns?: number;
  /** Most tool calls one assistant turn may fan out to. Extras are blocked. Defaults to 8. */
  readonly maxToolCallsPerTurn?: number;
  /**
   * Cost-aware retry for model calls that fail before producing any usage.
   * Every retry takes a real hold from the run's BudgetMeter. A pre-stream
   * failure cancels that hold and records measured zero; a successful retry
   * settles provider usage. Worst-case reserved exposure is still capped, so a
   * zero-spend error storm cannot retry forever. A retry policy requires a
   * budget: there is no denomination to reserve without one.
   */
  readonly retry?: {
    /** Worst-case spend the run will expose to retries, in the budget's denomination. */
    readonly maxSpend: number;
    /** First backoff, doubled each attempt. Deterministic — no jitter. Defaults to 250ms. */
    readonly backoffMs?: number;
  };
}

export interface NormalizedBreakers {
  readonly repeatedToolCalls: number;
  readonly repeatedToolCallWindowTurns: number;
  readonly noProgressTurns: number;
  readonly maxToolCallsPerTurn: number;
  readonly retryMaxSpend: number | undefined;
  readonly retryBackoffMs: number;
}

const DEFAULT_REPEATED_TOOL_CALLS = 3;
const DEFAULT_REPEATED_TOOL_CALL_WINDOW_TURNS = 8;
const DEFAULT_NO_PROGRESS_TURNS = 3;
const DEFAULT_MAX_TOOL_CALLS_PER_TURN = 8;
const DEFAULT_RETRY_BACKOFF_MS = 250;

export function normalizeRunBreakers(
  breakers: RunBreakers,
  hasBudget: boolean,
): NormalizedBreakers {
  const repeatedToolCalls = breakers.repeatedToolCalls ?? DEFAULT_REPEATED_TOOL_CALLS;
  const repeatedToolCallWindowTurns = breakers.repeatedToolCallWindowTurns ??
    DEFAULT_REPEATED_TOOL_CALL_WINDOW_TURNS;
  const noProgressTurns = breakers.noProgressTurns ?? DEFAULT_NO_PROGRESS_TURNS;
  const maxToolCallsPerTurn = breakers.maxToolCallsPerTurn ?? DEFAULT_MAX_TOOL_CALLS_PER_TURN;
  for (const value of [
    repeatedToolCalls,
    repeatedToolCallWindowTurns,
    noProgressTurns,
    maxToolCallsPerTurn,
  ]) {
    if (!Number.isSafeInteger(value) || value <= 0) {
      throw new Error("cave_breaker_threshold_invalid");
    }
  }
  if (breakers.retry !== undefined && !hasBudget) {
    throw new Error("cave_breaker_retry_requires_budget");
  }
  if (breakers.retry !== undefined &&
      (!Number.isFinite(breakers.retry.maxSpend) || breakers.retry.maxSpend <= 0)) {
    throw new Error("cave_breaker_retry_spend_invalid");
  }
  const retryBackoffMs = breakers.retry?.backoffMs ?? DEFAULT_RETRY_BACKOFF_MS;
  if (!Number.isSafeInteger(retryBackoffMs) || retryBackoffMs < 0) {
    throw new Error("cave_breaker_retry_backoff_invalid");
  }
  return Object.freeze({
    repeatedToolCalls,
    repeatedToolCallWindowTurns,
    noProgressTurns,
    maxToolCallsPerTurn,
    retryMaxSpend: breakers.retry?.maxSpend,
    retryBackoffMs,
  });
}

/** One breaker decision, recorded on the receipt so a break is never silent. */
export interface BreakerEvent {
  readonly kind: "loop_detected" | "no_progress" | "fan_out_blocked" | "retry_attempted" | "retry_exhausted";
  readonly tool: string | undefined;
  /** Repeats for a loop, identical turns for no-progress, blocked calls for fan-out, attempt number for a retry. */
  readonly count: number;
  /** The call hash for a loop break, so the offending window is identifiable. */
  readonly signature: string | undefined;
  /** Worst-case hold taken for this retry, in the run budget's denomination. */
  readonly reservedSpend?: number;
  /** Provider-measured spend, zero for the only retryable pre-stream failure. */
  readonly measuredSpend?: number;
  /** Why measuredSpend is trustworthy, or why worst-case settlement was used. */
  readonly spendBasis?: "pre_stream_no_usage" | "provider_reported" | "unavailable_worst_case";
}

type ToolRepeat = { turns: number[]; previousFailed: boolean };

/**
 * The breaker bookkeeping for one run. Every method is pure counting over
 * hashes the runtime already has in hand.
 */
export class BreakerState {
  readonly config: NormalizedBreakers;
  private readonly repeats = new Map<string, ToolRepeat>();
  private readonly hashByToolCallId = new Map<string, string>();
  private readonly events: BreakerEvent[] = [];
  private lastTurnSignature: string | undefined;
  private repeatedTurns = 0;
  private currentTurnKey: unknown;
  private completedTurns = 0;
  private currentTurnFanOut = 0;
  private trip: "loop_detected" | "no_progress" | undefined;

  constructor(config: NormalizedBreakers) {
    this.config = config;
  }

  /** The break this run has already decided on, if any. */
  get tripped(): "loop_detected" | "no_progress" | undefined {
    return this.trip;
  }

  get recorded(): readonly BreakerEvent[] {
    return Object.freeze(this.events.map((event) => Object.freeze({ ...event })));
  }

  /**
   * Count one tool call. Returns true when it must be blocked — because it is
   * the repeat that trips the loop breaker, or because its turn has already
   * fanned out as far as it may.
   */
  observeToolCall(input: {
    toolCallId: string;
    toolName: string;
    args: unknown;
    allowRepeat: boolean;
    turnKey: unknown;
  }): { block: boolean; reason: string | undefined } {
    if (input.turnKey !== this.currentTurnKey) {
      this.currentTurnKey = input.turnKey;
      this.currentTurnFanOut = 0;
    }
    this.currentTurnFanOut++;
    if (this.currentTurnFanOut > this.config.maxToolCallsPerTurn) {
      this.events.push(Object.freeze({
        kind: "fan_out_blocked",
        tool: input.toolName,
        count: this.currentTurnFanOut,
        signature: undefined,
      }));
      return { block: true, reason: "cave_fan_out_cap_exceeded" };
    }
    // A tool whose whole job is to be called again — polling a queue, waiting
    // on a build — is legitimately repetitive and opts out of the loop count.
    if (input.allowRepeat) return { block: false, reason: undefined };
    const signature = callSignature(input.toolName, input.args);
    this.hashByToolCallId.set(input.toolCallId, signature);
    const entry = this.repeats.get(signature) ?? { turns: [], previousFailed: false };
    if (entry.previousFailed) {
      // The previous identical attempt failed, so this one is a necessary
      // retry, not a re-traversal. Start the window again rather than counting
      // work the run had to pay for anyway.
      entry.turns = [];
      entry.previousFailed = false;
    }
    // Calls execute before the assistant turn completes. Tool-free turns still
    // advance completedTurns in observeTurn, so every real assistant turn ages
    // this window rather than only turns that happen to call a tool.
    const callTurn = this.completedTurns + 1;
    const oldestIncludedTurn = callTurn - this.config.repeatedToolCallWindowTurns + 1;
    entry.turns = entry.turns.filter((turn) => turn >= oldestIncludedTurn);
    entry.turns.push(callTurn);
    this.repeats.set(signature, entry);
    if (entry.turns.length >= this.config.repeatedToolCalls) {
      this.trip ??= "loop_detected";
      this.events.push(Object.freeze({
        kind: "loop_detected",
        tool: input.toolName,
        count: entry.turns.length,
        signature,
      }));
      return { block: true, reason: "cave_tool_call_loop_detected" };
    }
    return { block: false, reason: undefined };
  }

  observeToolResult(toolCallId: string, isError: boolean): void {
    const signature = this.hashByToolCallId.get(toolCallId);
    if (signature === undefined) return;
    this.hashByToolCallId.delete(toolCallId);
    const entry = this.repeats.get(signature);
    if (entry !== undefined) entry.previousFailed = isError;
  }

  /**
   * Fold one completed turn into the no-progress window. Tool identity is part
   * of the signature; equal output from different operations is not equality.
   * A successful declared write resets the window. Generic runtime cannot
   * inspect arbitrary host state, so treating write text as proof of no change
   * would be an unsafe false stop.
   */
  observeTurn(
    conclusion: string,
    toolResults: readonly unknown[],
    stateChanged = false,
  ): void {
    this.completedTurns++;
    if (stateChanged) {
      this.lastTurnSignature = undefined;
      this.repeatedTurns = 0;
      return;
    }
    const signature = sha256(stableStringify({ conclusion, toolResults }));
    if (signature === this.lastTurnSignature) this.repeatedTurns++;
    else this.repeatedTurns = 1;
    this.lastTurnSignature = signature;
    if (this.repeatedTurns >= this.config.noProgressTurns) {
      this.trip ??= "no_progress";
      this.events.push(Object.freeze({
        kind: "no_progress",
        tool: undefined,
        count: this.repeatedTurns,
        signature,
      }));
    }
  }

  /**
   * Check cumulative worst-case exposure recorded on receipt events. False
   * means allowance cannot cover another attempt; actual BudgetMeter hold is
   * taken separately before recordRetryAttempt makes the attempt auditable.
   */
  retryExposureAvailable(amount: number, attempt: number): boolean {
    const allowance = this.config.retryMaxSpend;
    if (allowance === undefined) return false;
    if (!Number.isFinite(amount) || amount <= 0) return false;
    const exposed = this.events.reduce((total, event) =>
      event.kind === "retry_attempted" ? total + (event.reservedSpend ?? 0) : total, 0);
    if (exposed + amount > allowance) {
      this.events.push(Object.freeze({
        kind: "retry_exhausted",
        tool: undefined,
        count: attempt,
        signature: undefined,
      }));
      return false;
    }
    return true;
  }

  /** Record one retry only after its real BudgetMeter hold succeeds. */
  recordRetryAttempt(amount: number, attempt: number): void {
    this.events.push({
      kind: "retry_attempted",
      tool: undefined,
      count: attempt,
      signature: undefined,
      reservedSpend: amount,
    });
  }

  /** Mark a retry reservation refused by the run's live meter. */
  recordRetryExhausted(attempt: number): void {
    this.events.push(Object.freeze({
      kind: "retry_exhausted",
      tool: undefined,
      count: attempt,
      signature: undefined,
    }));
  }

  /** Settle receipt evidence for one already-recorded retry attempt. */
  settleRetry(
    attempt: number,
    measuredSpend: number,
    spendBasis: NonNullable<BreakerEvent["spendBasis"]>,
  ): void {
    // Attempt numbers restart for each model call. Settle the newest matching
    // event that has not already been settled, never an earlier call's retry.
    let event: BreakerEvent | undefined;
    for (let index = this.events.length - 1; index >= 0; index--) {
      const candidate = this.events[index]!;
      if (candidate.kind === "retry_attempted" && candidate.count === attempt &&
          candidate.measuredSpend === undefined) {
        event = candidate;
        break;
      }
    }
    if (event === undefined || !Number.isFinite(measuredSpend) || measuredSpend < 0) {
      throw new Error("cave_retry_accounting_invalid");
    }
    (event as { measuredSpend?: number; spendBasis?: BreakerEvent["spendBasis"] }).measuredSpend = measuredSpend;
    (event as { measuredSpend?: number; spendBasis?: BreakerEvent["spendBasis"] }).spendBasis = spendBasis;
  }

  /** Deterministic exponential backoff. No jitter: a breaker must be reproducible. */
  backoffMs(attempt: number): number {
    return this.config.retryBackoffMs * 2 ** Math.max(0, attempt - 1);
  }
}

export function callSignature(toolName: string, args: unknown): string {
  return sha256(stableStringify({ tool: toolName, args: args ?? null }));
}

import type { BreakerEvent } from "./breakers.js";
import { catalogSearchCeiling } from "./catalog.js";
import { normalizeCompaction, type CompactionOptions, type NormalizedCompaction } from "./compaction.js";

/** Versioned cross-package wire identity for an SDK economic receipt. */
export const AGENT_RUN_RECEIPT_SCHEMA = "caveman.agent.run-receipt.v1" as const;

/**
 * The economic runtime's meter.
 *
 * Every figure here is a public-catalog **list-price subtotal**, not an
 * invoice. A USD budget can only bind on a model the catalog prices; an
 * unpriced model fails closed rather than treating an unknown price as zero.
 *
 * Denominations are runtime-gated: dollars only where the runtime
 * honestly meters dollars — the API-key provider paths this package drives —
 * and raw tokens where it does not. A run declares exactly one.
 */
export type BudgetDenomination = "usd" | "tokens";

/**
 * Why a run stopped issuing calls. `complete` is the ordinary end of an agent
 * loop; every other value means the runtime stopped the run between calls with
 * partial work in hand. Unknown values are not representable — a stop reason is
 * always one of these, so a consumer switch can fail closed on the default.
 */
export type RunStopReason =
  | "complete"
  | "budget_exhausted"
  | "deadline"
  | "loop_detected"
  | "no_progress"
  | "wallet_revoked"
  // The run hit its hard model-call ceiling (RunOptions.maxModelCalls, default
  // 64). Like every other stop reason this ends the run gracefully between
  // calls with the partial work, usage, and receipt in hand — never a throw
  // that would destroy the ledger of what was already spent.
  | "call_budget_exhausted";

/**
 * Smallest output allowance the clamp will hand a provider call. Below it a
 * clamped call buys a truncated fragment rather than progress, so the runtime
 * enters the exhaustion ladder instead of spending on one.
 */
export const OUTPUT_CLAMP_FLOOR_TOKENS = 256;

/**
 * Provider-side turn framing (role markers, tool-call envelopes) that our own
 * serialization of a context does not contain. Added per message when ceilings
 * are computed so the reserve stays an over-estimate.
 */
const MESSAGE_FRAMING_TOKENS = 16;

export interface RunBudget {
  /** Hard cap in USD at public catalog list prices. Mutually exclusive with `maxTokens`. */
  readonly maxUsd?: number;
  /** Hard cap in provider-counted tokens. Mutually exclusive with `maxUsd`. */
  readonly maxTokens?: number;
  /** Staged release: the run starts metered against this, not `maxUsd`. */
  readonly initialUsd?: number;
  /** Staged release: the run starts metered against this, not `maxTokens`. */
  readonly initialTokens?: number;
  /** Output floor for the clamp rung. Defaults to {@link OUTPUT_CLAMP_FLOOR_TOKENS}. */
  readonly outputFloorTokens?: number;
  /**
   * What the run does as reserve headroom approaches exhaustion. `"compact"`
   * is the default: compress context while the same cap can still fund the
   * rewrite and useful work. `"stop"` skips compaction and clamps/stops only
   * when the next call itself no longer fits.
   */
  readonly onExhausted?: "compact" | "stop";
  /** Tuning for the compaction rung. Ignored when `onExhausted` is `"stop"`. */
  readonly compaction?: CompactionOptions;
}

export interface NormalizedBudget {
  readonly denomination: BudgetDenomination;
  readonly max: number;
  readonly initial: number;
  readonly outputFloorTokens: number;
  readonly onExhausted: "compact" | "stop";
  readonly compaction: NormalizedCompaction;
}

/**
 * Validate a caller-supplied budget. Fails closed: an ambiguous, unbounded, or
 * self-contradicting budget is rejected before the first provider call rather
 * than silently degrading into no cap at all.
 */
export function normalizeRunBudget(budget: RunBudget): NormalizedBudget {
  const usd = budget.maxUsd !== undefined;
  const tokens = budget.maxTokens !== undefined;
  if (usd === tokens) throw new Error("cave_budget_denomination_ambiguous");
  const denomination: BudgetDenomination = usd ? "usd" : "tokens";
  const max = usd ? budget.maxUsd! : budget.maxTokens!;
  if (!Number.isFinite(max) || max <= 0) throw new Error("cave_budget_max_invalid");
  if (denomination === "tokens" && !Number.isSafeInteger(max)) {
    throw new Error("cave_budget_max_invalid");
  }
  const wrongInitial = denomination === "usd" ? budget.initialTokens : budget.initialUsd;
  if (wrongInitial !== undefined) throw new Error("cave_budget_denomination_ambiguous");
  const declaredInitial = denomination === "usd" ? budget.initialUsd : budget.initialTokens;
  const initial = declaredInitial ?? max;
  if (!Number.isFinite(initial) || initial <= 0 || initial > max) {
    throw new Error("cave_budget_initial_invalid");
  }
  if (denomination === "tokens" && !Number.isSafeInteger(initial)) {
    throw new Error("cave_budget_initial_invalid");
  }
  const outputFloorTokens = budget.outputFloorTokens ?? OUTPUT_CLAMP_FLOOR_TOKENS;
  if (!Number.isSafeInteger(outputFloorTokens) || outputFloorTokens <= 0) {
    throw new Error("cave_budget_output_floor_invalid");
  }
  const onExhausted = budget.onExhausted ?? "compact";
  if (onExhausted !== "compact" && onExhausted !== "stop") {
    throw new Error("cave_budget_on_exhausted_invalid");
  }
  return Object.freeze({
    denomination,
    max,
    initial,
    outputFloorTokens,
    onExhausted,
    compaction: normalizeCompaction(budget.compaction),
  });
}

/** Identity and shape of one prospective provider call. */
export interface CallCeiling {
  readonly provider: string;
  readonly model: string;
  /** Upper bound on the request's input tokens. Never an estimate that can be low. */
  readonly inputTokenCeiling: number;
  /** The output allowance this call would ask for. */
  readonly outputTokenCap: number;
}

export interface BudgetReservation {
  readonly amount: number;
  readonly outputTokenCap: number;
  settled: boolean;
}

/**
 * Worst-case price of one call in the meter's denomination, or `undefined` when
 * the catalog cannot price the model. Undefined is a hard stop for a USD
 * budget, never a zero: a cap that cannot be measured is not a cap.
 */
export function callCeilingCost(
  denomination: BudgetDenomination,
  call: CallCeiling,
  outputTokens: number,
): number | undefined {
  if (!Number.isSafeInteger(call.inputTokenCeiling) || call.inputTokenCeiling < 0 ||
      !Number.isSafeInteger(outputTokens) || outputTokens < 0) {
    return undefined;
  }
  if (denomination === "tokens") return call.inputTokenCeiling + outputTokens;
  return catalogSearchCeiling(
    `${call.provider}/${call.model}`,
    call.inputTokenCeiling,
    outputTokens,
  );
}

/**
 * Whether the remaining budget covers this call at its full output allowance.
 * Pure: unlike {@link planCall} it takes nothing, so it is safe to ask at any
 * point that is only deciding, not spending.
 */
export function callFitsBudget(meter: BudgetMeter, call: CallCeiling): boolean {
  if (meter.revoked || meter.capBreached) return false;
  const full = callCeilingCost(meter.denomination, call, call.outputTokenCap);
  return full !== undefined && full <= meter.remaining();
}

/** True when the public catalog prices this model, so a USD budget can bind on it. */
export function modelIsPriced(provider: string, model: string): boolean {
  return catalogSearchCeiling(`${provider}/${model}`, 0, 0) !== undefined;
}

/**
 * Upper bound on the input tokens of a request carrying `serialized` bytes over
 * `messageCount` messages.
 *
 * Every production tokenizer in the catalog is byte-level BPE, so a token
 * always covers at least one byte and the byte count is a true ceiling on the
 * token count. Provider-side turn framing is added on top, and the model's own
 * context window caps the result because a larger request cannot be served at
 * all. Under-reserving would let a run spend past its cap, so this stays a
 * hard over-estimate.
 *
 * This bound intentionally over-reserves. A provider count-tokens endpoint could
 * make it tighter, but the byte bound is the available ceiling in this layer and
 * never under-reserves.
 */
export function inputTokenCeiling(
  serializedBytes: number,
  messageCount: number,
  contextWindow: number,
): number {
  const framed = serializedBytes + Math.max(0, messageCount) * MESSAGE_FRAMING_TOKENS;
  const window = Number.isSafeInteger(contextWindow) && contextWindow > 0
    ? contextWindow
    : Number.MAX_SAFE_INTEGER;
  return Math.max(0, Math.min(framed, window));
}

/**
 * Byte length of a context as this process can serialize it. Unserializable
 * context returns `undefined`, which callers treat as "assume the whole context
 * window" rather than guessing a smaller number.
 */
export function serializedContextBytes(value: unknown): number | undefined {
  try {
    const encoded = JSON.stringify(value);
    if (encoded === undefined) return undefined;
    return Buffer.byteLength(encoded, "utf8");
  } catch {
    return undefined;
  }
}

/** A subagent wallet and the hold it placed on its parent. */
export interface BudgetCarve {
  readonly child: BudgetMeter;
  readonly reservation: BudgetReservation;
}

/** One staged release of budget. */
export interface BudgetTranche {
  readonly amount: number;
  readonly reason: string;
  readonly atCall: number;
}

/**
 * The per-run (or per-wallet) ledger.
 *
 * Invariant this class exists to hold: settled spend plus outstanding
 * reservations never exceeds `max`. Reservations are taken before a provider
 * request and replaced by the measured cost afterwards, so a call that turns
 * out cheaper than its worst case returns the difference to the run.
 */
export class BudgetMeter {
  readonly denomination: BudgetDenomination;
  readonly max: number;
  readonly outputFloorTokens: number;
  readonly onExhausted: "compact" | "stop";
  readonly compaction: NormalizedCompaction;
  private releasedAmount: number;
  private settledAmount = 0;
  private reservedAmount = 0;
  private revokedFlag = false;
  private breachedFlag = false;
  private callIndex = 0;
  private readonly trancheLog: BudgetTranche[] = [];
  private readonly liveWallets = new Set<BudgetMeter>();

  constructor(normalized: NormalizedBudget) {
    this.denomination = normalized.denomination;
    this.max = normalized.max;
    this.outputFloorTokens = normalized.outputFloorTokens;
    this.onExhausted = normalized.onExhausted;
    this.compaction = normalized.compaction;
    this.releasedAmount = normalized.initial;
  }

  /** Spend the meter has actually measured. */
  get settled(): number {
    return this.settledAmount;
  }

  /** Total released so far. Equals `max` unless the run uses tranches. */
  get released(): number {
    return this.releasedAmount;
  }

  get revoked(): boolean {
    return this.revokedFlag;
  }

  /**
   * True once measured spend has crossed `max`.
   *
   * The runtime never *chooses* to spend past max: every call is reserved at
   * its worst case first. A breach means reality came in above what the
   * provider's own contract allowed us to bound — and when it does, the ledger
   * records the real amount rather than clamping it, because a clamped ledger
   * is fake accounting. A breach is loud, signed on the receipt, and terminal:
   * a breached meter funds nothing further.
   */
  get capBreached(): boolean {
    return this.breachedFlag;
  }

  /** Signed amount past `max`. Zero when the cap held. */
  get overspent(): number {
    if (this.settledAmount <= this.max) return 0;
    const over = this.settledAmount - this.max;
    return this.denomination === "usd" ? roundUsd(over) : over;
  }

  get tranches(): readonly BudgetTranche[] {
    return Object.freeze([...this.trancheLog]);
  }

  /** Budget available to a new reservation right now. */
  remaining(): number {
    return Math.max(0, this.releasedAmount - this.settledAmount - this.reservedAmount);
  }

  /** Budget that could still be released without breaching `max`. */
  releasable(): number {
    return Math.max(0, this.max - this.releasedAmount);
  }

  /**
   * Release a further tranche. Throws when it would breach `max`: this is
   * pre-flight validation at a developer-controlled checkpoint, so the caller
   * asked for something the contract cannot grant.
   */
  release(amount: number, reason: string): BudgetTranche {
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error("cave_budget_release_invalid");
    }
    if (this.denomination === "tokens" && !Number.isSafeInteger(amount)) {
      throw new Error("cave_budget_release_invalid");
    }
    if (typeof reason !== "string" || reason.trim() === "") {
      throw new Error("cave_budget_release_reason_required");
    }
    if (this.revokedFlag) throw new Error("cave_budget_revoked");
    // A breached ledger is dead. Releasing into it would record a tranche and
    // raise an escalation for money that can never be spent, and would read on
    // the receipt as a run that was still being funded after it went past cap.
    if (this.breachedFlag) throw new Error("cave_budget_cap_breached");
    if (amount > this.releasable()) throw new Error("cave_budget_release_exceeds_max");
    this.releasedAmount += amount;
    const tranche: BudgetTranche = Object.freeze({
      amount,
      reason,
      atCall: this.callIndex,
    });
    this.trancheLog.push(tranche);
    return tranche;
  }

  /**
   * Hold `amount` against the ledger. Returns `undefined` when it does not fit,
   * which is the caller's signal to clamp, compact, or stop — never to proceed.
   */
  reserve(amount: number, outputTokenCap: number): BudgetReservation | undefined {
    const held = this.hold(amount, outputTokenCap);
    if (held !== undefined) this.callIndex++;
    return held;
  }

  private hold(amount: number, outputTokenCap: number): BudgetReservation | undefined {
    if (this.revokedFlag || this.breachedFlag) return undefined;
    if (!Number.isFinite(amount) || amount < 0) return undefined;
    if (amount > this.remaining()) return undefined;
    this.reservedAmount += amount;
    return { amount, outputTokenCap, settled: false };
  }

  /**
   * Carve a subagent wallet out of what this meter has left.
   *
   * The whole wallet is held against the parent the moment the child is
   * spawned, before any await, so parallel spawns cannot both be funded from
   * the same remainder. The child is a meter in its own right, hard-capped at
   * the wallet, and whatever it does not spend returns to the parent when the
   * carve settles. `undefined` means the parent cannot fund this wallet.
   */
  carve(amount: number): BudgetCarve | undefined {
    if (!Number.isFinite(amount) || amount <= 0) return undefined;
    if (this.denomination === "tokens" && !Number.isSafeInteger(amount)) return undefined;
    const reservation = this.hold(amount, 0);
    if (reservation === undefined) return undefined;
    const child = new BudgetMeter({
      denomination: this.denomination,
      max: amount,
      initial: amount,
      outputFloorTokens: this.outputFloorTokens,
      onExhausted: this.onExhausted,
      compaction: this.compaction,
    });
    this.liveWallets.add(child);
    return Object.freeze({ child, reservation });
  }

  /** Return a carved wallet's unspent remainder to this meter. */
  settleCarve(carve: BudgetCarve): void {
    this.liveWallets.delete(carve.child);
    this.settle(carve.reservation, carve.child.settled);
  }

  /**
   * Replace a reservation with the measured cost of the call it covered.
   *
   * `actual` is recorded as it came in. It is never clamped to the reservation
   * and never floored at `max`: a ledger that quietly rewrites what a call cost
   * is a fake ledger, and the honest failure is a flagged breach, not a
   * flattering number.
   */
  settle(reservation: BudgetReservation, actual: number): void {
    if (reservation.settled) throw new Error("cave_budget_reservation_double_settle");
    reservation.settled = true;
    this.reservedAmount = Math.max(0, this.reservedAmount - reservation.amount);
    if (!Number.isFinite(actual)) {
      // A NaN/Infinity measured cost is not knowable, so it fails closed at the
      // reservation's worst case rather than booking $0. A call
      // whose real cost we cannot read is never a free call — booking zero would
      // be the flattering number this ledger refuses to write.
      this.settledAmount += reservation.amount;
    } else if (actual > 0) {
      this.settledAmount += actual;
    }
    if (this.settledAmount > this.max) this.breachedFlag = true;
  }

  /** Drop a reservation whose call never reached the provider. */
  cancel(reservation: BudgetReservation): void {
    if (reservation.settled) return;
    reservation.settled = true;
    this.reservedAmount = Math.max(0, this.reservedAmount - reservation.amount);
  }

  /**
   * Stop this meter funding anything further, and every wallet carved from it.
   * A revoked child stops between its own calls like any other exhaustion —
   * nothing in flight is interrupted.
   */
  revoke(): void {
    this.revokedFlag = true;
    for (const wallet of this.liveWallets) wallet.revoke();
  }

  /** Number of reservations taken so far. Used to stamp tranche history. */
  get calls(): number {
    return this.callIndex;
  }
}

/**
 * One provider call as the receipt records it.
 *
 * `estimatedUsd` is a public-catalog list-price subtotal for this call — what
 * the call would list at, never what any invoice said. `unpriced` marks a call
 * the catalog could not price at all, whose contribution to the total is an
 * honest zero rather than a measured amount.
 */
export interface ReceiptCall {
  readonly provider: string;
  readonly model: string;
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly cacheReadTokens: number;
  readonly cacheWriteTokens: number;
  readonly reasoningTokens: number;
  readonly estimatedUsd: number;
  readonly unpriced: boolean;
  /** How the tokens above were arrived at. `unavailable` means the provider's report was unreadable. */
  readonly usageBasis: "provider_reported" | "unavailable";
  /** The output allowance this call was given when the budget lowered it below the configured cap. */
  readonly clampedOutputTokens: number | undefined;
}

/**
 * One compaction event.
 *
 * `meteredCost` is REAL: what the summarization call actually cost, in the
 * run's denomination, zero for a free eviction. `modeledNetTokens` is MODELED
 * and labelled so — the context reduction this rewrite bought over the working
 * calls that actually followed it, net of the cache-write penalty the rewrite
 * forced. It is not a saving and is never called one.
 */
export interface ReceiptCompaction {
  readonly index: number;
  readonly tier: "evicted" | "summarized";
  readonly preTokens: number;
  readonly postTokens: number;
  readonly pinnedSegmentIds: readonly string[];
  readonly elidedSegmentDigests: readonly string[];
  readonly summarySchemaVersion: number | undefined;
  /**
   * The cache state the provider's own usage reported on the last working call,
   * recorded as evidence. The affordability model prices the summarizer COLD
   * whatever this says: the rewrite diverges from the working call's prefix at
   * its first changed message, so a warm read there is not evidence for a warm
   * read here.
   */
  readonly cacheState: "warm" | "cold" | "unknown";
  readonly meteredCost: number;
  readonly meteredBasis: "measured";
  readonly modeledNetTokens: number;
  readonly modeledBasis: "modeled";
  /** Working calls that actually followed this compaction, the multiplier in the modeled figure. */
  readonly workingCallsAfter: number;
}

/**
 * Tool activity for one tool name. Tools carry no model spend of their own —
 * a subagent tool's spend is its nested receipt under `subagents`.
 */
export interface ReceiptTool {
  readonly name: string;
  readonly calls: number;
  readonly errors: number;
}

/**
 * The economic receipt every run returns.
 *
 * Every money figure here is a public-catalog price estimate. It is not an
 * invoice, bill, or provider savings claim.
 */
export interface RunReceipt {
  readonly schema: typeof AGENT_RUN_RECEIPT_SCHEMA;
  readonly runId: string;
  readonly agentId: string;
  readonly basis: "estimated_list_price_subtotal";
  readonly claimBasis: "inferred";
  readonly stopReason: RunStopReason;
  /** `none` when the run declared no budget: the receipt still reports, nothing enforces. */
  readonly denomination: BudgetDenomination | "none";
  readonly max: number | undefined;
  readonly released: number | undefined;
  /** Metered spend in the run's own denomination, `undefined` without a budget. */
  readonly spent: number | undefined;
  /**
   * True when measured spend crossed `max`. The runtime never chooses to spend
   * past max — every call is reserved at its worst case first — so this means
   * a provider-side amount came in above what could be bounded. The receipt
   * never shows `spent > max` without this flag set.
   */
  readonly capBreached: boolean;
  /**
   * Signed amount **this run's own meter** went past its `max`, zero when its
   * own cap held. Deliberately not a tree total: settling a subagent's carve
   * books the child's real spend against this run, so a child's overspend
   * usually shows up here too and adding the two would count the same money
   * twice. Each subagent's own figure is on its own receipt under `subagents`.
   */
  readonly overspent: number;
  /** Estimated list-price subtotal of this run and everything under it. */
  readonly totalEstimatedUsd: number;
  readonly totalTokens: number;
  /** True when any call in this receipt or its subagents went unpriced. */
  readonly unpriced: boolean;
  readonly calls: readonly ReceiptCall[];
  readonly tools: readonly ReceiptTool[];
  readonly subagents: readonly RunReceipt[];
  readonly tranches: readonly BudgetTranche[];
  /** Every deterministic breaker decision this run made, so a break is never silent. */
  readonly breakers: readonly BreakerEvent[];
  /** Every context compaction, with its real cost and its modeled effect kept apart. */
  readonly compactions: readonly ReceiptCompaction[];
}

/**
 * Accumulates one run's receipt. The runtime feeds it from the same provider
 * evidence the run result is built from, so the receipt and the result can
 * never disagree about what happened.
 */
/** A compaction as it is recorded while the run is still going. */
export interface PendingCompaction {
  readonly tier: "evicted" | "summarized";
  readonly preTokens: number;
  readonly postTokens: number;
  readonly pinnedSegmentIds: readonly string[];
  readonly elidedSegmentDigests: readonly string[];
  readonly summarySchemaVersion: number | undefined;
  readonly cacheState: "warm" | "cold" | "unknown";
  readonly meteredCost: number;
}

export class ReceiptRecorder {
  private readonly callLog: ReceiptCall[] = [];
  private readonly toolLog = new Map<string, { calls: number; errors: number }>();
  private readonly subagentLog: RunReceipt[] = [];
  private readonly compactionLog: Array<PendingCompaction & { callsBefore: number }> = [];

  recordCall(call: ReceiptCall): void {
    this.callLog.push(Object.freeze({ ...call }));
  }

  /**
   * The call watermark is taken here, not passed in.
   *
   * A compaction is recorded after its own summarizer call has already been
   * logged, so anything the caller counted beforehand is one too low and every
   * compaction would claim a working call it never bought. Reading the log's
   * own length at record time makes "calls after this rewrite" mean exactly
   * that.
   */
  recordCompaction(compaction: PendingCompaction): void {
    this.compactionLog.push(Object.freeze({
      ...compaction,
      callsBefore: this.callLog.length,
    }));
  }

  recordToolCall(name: string): void {
    const entry = this.toolLog.get(name) ?? { calls: 0, errors: 0 };
    entry.calls++;
    this.toolLog.set(name, entry);
  }

  recordToolOutcome(name: string, isError: boolean): void {
    if (!isError) return;
    const entry = this.toolLog.get(name) ?? { calls: 0, errors: 0 };
    entry.errors++;
    this.toolLog.set(name, entry);
  }

  recordSubagent(receipt: RunReceipt): void {
    this.subagentLog.push(receipt);
  }

  build(input: {
    runId: string;
    agentId: string;
    stopReason: RunStopReason;
    meter: BudgetMeter | undefined;
    breakers?: readonly BreakerEvent[];
  }): RunReceipt {
    const ownUsd = this.callLog.reduce((total, call) => total + call.estimatedUsd, 0);
    const ownTokens = this.callLog.reduce(
      (total, call) => total + call.inputTokens + call.outputTokens +
        call.cacheReadTokens + call.cacheWriteTokens,
      0,
    );
    const nestedUsd = this.subagentLog.reduce(
      (total, child) => total + child.totalEstimatedUsd,
      0,
    );
    const nestedTokens = this.subagentLog.reduce(
      (total, child) => total + child.totalTokens,
      0,
    );
    const denomination = input.meter?.denomination ?? "none";
    return Object.freeze({
      schema: AGENT_RUN_RECEIPT_SCHEMA,
      runId: input.runId,
      agentId: input.agentId,
      basis: "estimated_list_price_subtotal",
      claimBasis: "inferred",
      stopReason: input.stopReason,
      denomination,
      max: input.meter?.max,
      released: input.meter?.released,
      spent: input.meter?.settled,
      // A breach anywhere under this run is a breach of this run. Wallets are
      // small carves off a larger parent, so a child outspending its wallet is
      // the ordinary shape of a breach — reading only the local meter would
      // report the cap held while money under it had already gone past.
      capBreached: (input.meter?.capBreached ?? false) ||
        this.subagentLog.some((child) => child.capBreached),
      // THIS level's own overspend, never a tree total. Settling a carve books
      // the child's real spend against the parent, so a child's overspend
      // usually pushes the parent past its own cap too — adding the two would
      // count the same dollars twice and can print a figure larger than the
      // whole tree spent. Each child's receipt carries its own.
      overspent: input.meter?.overspent ?? 0,
      totalEstimatedUsd: roundUsd(ownUsd + nestedUsd),
      totalTokens: ownTokens + nestedTokens,
      unpriced: this.callLog.some((call) => call.unpriced) ||
        this.subagentLog.some((child) => child.unpriced),
      calls: Object.freeze([...this.callLog]),
      tools: Object.freeze([...this.toolLog].map(([name, entry]) => Object.freeze({
        name,
        calls: entry.calls,
        errors: entry.errors,
      }))),
      subagents: Object.freeze([...this.subagentLog]),
      tranches: input.meter?.tranches ?? Object.freeze([]),
      breakers: input.breakers ?? Object.freeze([]),
      // The modeled effect of a compaction depends on how many working calls
      // actually followed it, which is knowable only now, at run end. Nothing
      // modeled is emitted before the run settles.
      compactions: Object.freeze(this.compactionLog.map((entry, index) => Object.freeze({
        index,
        tier: entry.tier,
        preTokens: entry.preTokens,
        postTokens: entry.postTokens,
        pinnedSegmentIds: Object.freeze([...entry.pinnedSegmentIds]),
        elidedSegmentDigests: Object.freeze([...entry.elidedSegmentDigests]),
        summarySchemaVersion: entry.summarySchemaVersion,
        cacheState: entry.cacheState,
        meteredCost: entry.meteredCost,
        meteredBasis: "measured" as const,
        modeledNetTokens: modeledNetTokens(
          entry,
          Math.max(0, this.callLog.length - entry.callsBefore),
        ),
        modeledBasis: "modeled" as const,
        workingCallsAfter: Math.max(0, this.callLog.length - entry.callsBefore),
      }))),
    });
  }
}

function roundUsd(value: number): number {
  return Math.round((value + Number.EPSILON) * 1e10) / 1e10;
}


/**
 * Local estimate: tokens the rewrite kept out of subsequent requests,
 * net of what the rewrite itself put back.
 *
 * The context shrank by `pre - post`, and each working call that followed it
 * carried the smaller context — that is the numerator. Against it stands the
 * rewrite's own cost: a compaction invalidates the cached prefix, so the next
 * request re-sends `post` tokens that would otherwise have been a cache read.
 * A figure that counted only the reduction would overstate the result, so the
 * penalty is subtracted here rather than footnoted.
 *
 * A negative result is kept signed. A compaction that did not pay for itself
 * says so.
 */
function modeledNetTokens(entry: PendingCompaction, workingCallsAfter: number): number {
  const reduction = (entry.preTokens - entry.postTokens) * workingCallsAfter;
  const cacheRewritePenalty = workingCallsAfter > 0 ? entry.postTokens : 0;
  return reduction - cacheRewritePenalty;
}

/**
 * What the escalation hook is told when a budget binds. Read-only:
 * the handler decides, the runtime applies. Every figure is in the run's own
 * denomination.
 */
export interface BudgetExhaustionContext {
  readonly denomination: BudgetDenomination;
  readonly max: number;
  readonly released: number;
  readonly spent: number;
  readonly remaining: number;
  /** How much could still be released without breaching `max`. */
  readonly releasable: number;
  /** Provider calls this run has already made. */
  readonly calls: number;
}

/**
 * Caller-side escalation for budget exhaustion.
 *
 * Called **between** calls, never mid-tool, and never with anything in flight.
 * Return `"stop"` to take the default outcome — partial work plus receipt — or
 * `{ release, reason }` to top up a tranche through the budget controller and carry
 * on. A release past `max` throws, because `max` is the contract.
 *
 * The embedding application owns this decision: ask a human, check a policy,
 * consult a quota. Nothing the model produces reaches it.
 *
 * Out of scope for v1: pausing a run and resuming it later from a serializable
 * handle. The hook is synchronous with the run it belongs to.
 */
export type BudgetExhaustionHandler = (
  context: BudgetExhaustionContext,
) => Promise<"stop" | { release: number; reason: string }>;

export function budgetExhaustionContext(meter: BudgetMeter): BudgetExhaustionContext {
  return Object.freeze({
    denomination: meter.denomination,
    max: meter.max,
    released: meter.released,
    spent: meter.settled,
    remaining: meter.remaining(),
    releasable: meter.releasable(),
    calls: meter.calls,
  });
}

const controllerMeters = new WeakMap<BudgetController, BudgetMeter>();

/**
 * The handle a developer uses to release staged budget.
 *
 * Tranches are released at **deterministic, developer-defined** checkpoints —
 * a plan produced, a build compiled, tests located. Nothing the model says can
 * reach this object: it exists only in the embedding application's own code and
 * in tool implementations the developer wrote, which keeps every model out of
 * the money path.
 *
 * A controller is bound to exactly one live run at a time and is inert outside
 * one, so a stale handle cannot quietly release budget into nothing.
 */
export class BudgetController {
  /**
   * Release a further tranche. Throws past `max`, at the release site: the
   * checkpoint asked for something the run's contract cannot grant, and that is
   * a programming error rather than a run outcome.
   */
  releaseBudget(amount: number, reason: string): BudgetTranche {
    return this.meter().release(amount, reason);
  }

  /** Metered spend so far, in the run's denomination. */
  get spent(): number {
    return this.meter().settled;
  }

  /** Budget available to the next call right now. */
  get remaining(): number {
    return this.meter().remaining();
  }

  /** Total released so far, across every tranche. */
  get released(): number {
    return this.meter().released;
  }

  get max(): number {
    return this.meter().max;
  }

  get denomination(): BudgetDenomination {
    return this.meter().denomination;
  }

  get tranches(): readonly BudgetTranche[] {
    return this.meter().tranches;
  }

  private meter(): BudgetMeter {
    const bound = controllerMeters.get(this);
    if (bound === undefined) throw new Error("cave_budget_controller_unbound");
    return bound;
  }
}

export function createBudgetController(): BudgetController {
  return new BudgetController();
}

/** Package-internal. Binds a controller to the run that owns its budget. */
export function bindBudgetController(
  controller: BudgetController,
  meter: BudgetMeter,
): void {
  if (controllerMeters.has(controller)) throw new Error("cave_budget_controller_in_use");
  controllerMeters.set(controller, meter);
}

/** Package-internal. Releases the binding when the run ends. */
export function unbindBudgetController(controller: BudgetController): void {
  controllerMeters.delete(controller);
}

/** What the meter says the runtime may do with the next provider call. */
export type CallPlan =
  | { readonly action: "proceed"; readonly reservation: BudgetReservation | undefined; readonly outputTokenCap: number }
  | { readonly action: "compact" }
  | { readonly action: "stop"; readonly reason: RunStopReason };

/**
 * The exhaustion ladder's arithmetic: full allowance, else a clamped allowance
 * down to the floor, else exhaustion. `compactionAvailable` lets the caller
 * insert the compaction rung between the full and clamped rungs.
 */
export function planCall(
  meter: BudgetMeter | undefined,
  call: CallCeiling,
  compactionAvailable: boolean,
): CallPlan {
  if (meter === undefined) {
    return { action: "proceed", reservation: undefined, outputTokenCap: call.outputTokenCap };
  }
  if (meter.revoked) return { action: "stop", reason: "wallet_revoked" };
  const full = callCeilingCost(meter.denomination, call, call.outputTokenCap);
  if (full === undefined) return { action: "stop", reason: "budget_exhausted" };
  const fullReservation = meter.reserve(full, call.outputTokenCap);
  if (fullReservation !== undefined) {
    return { action: "proceed", reservation: fullReservation, outputTokenCap: call.outputTokenCap };
  }
  if (compactionAvailable) return { action: "compact" };
  const clampedCap = affordableOutputTokens(meter, call);
  if (clampedCap === undefined) return { action: "stop", reason: "budget_exhausted" };
  const clampedCost = callCeilingCost(meter.denomination, call, clampedCap);
  if (clampedCost === undefined) return { action: "stop", reason: "budget_exhausted" };
  const clampedReservation = meter.reserve(clampedCost, clampedCap);
  if (clampedReservation === undefined) return { action: "stop", reason: "budget_exhausted" };
  return { action: "proceed", reservation: clampedReservation, outputTokenCap: clampedCap };
}

/**
 * Largest output allowance at or above the floor that the remaining budget can
 * still fund for this call, or `undefined` when even the floor does not fit.
 *
 * Cost is monotone in output tokens, so this is a binary search rather than a
 * second copy of the catalog's rate table.
 */
export function affordableOutputTokens(
  meter: BudgetMeter,
  call: CallCeiling,
): number | undefined {
  const remaining = meter.remaining();
  const floor = meter.outputFloorTokens;
  if (call.outputTokenCap < floor) return undefined;
  const floorCost = callCeilingCost(meter.denomination, call, floor);
  if (floorCost === undefined || floorCost > remaining) return undefined;
  let low = floor;
  let high = call.outputTokenCap;
  while (low < high) {
    const middle = low + Math.ceil((high - low) / 2);
    const cost = callCeilingCost(meter.denomination, call, middle);
    if (cost !== undefined && cost <= remaining) low = middle;
    else high = middle - 1;
  }
  return low;
}

