test("an error storm exhausts the retry allowance instead of the wallet", async () => {
  const defined = agent({
    id: "breaker-retry-storm",
    instructions: "Reply.",
    model: "anthropic/claude-haiku-4-5",
    sandbox: "fixture",
  });
