test("B1: a breached meter funds nothing further, not even a clamped call", () => {
  const meter = new BudgetMeter(normalizeRunBudget({ maxUsd: 1 }));
  const held = meter.reserve(0.5, 1_000);
  meter.settle(held, 1.4);
