  await run(second, "Second prompt.", {
    ensureRuntime: false,
    conversation,
    model,
    streamFn,
    providerPayloadContract: "pi-on-payload-v1",
  });

  assert.match(JSON.stringify(forwarded[1].payload.system), /NEW INSTRUCTIONS/);
