    'module?.["require"](name);',
    "require.bind(null)(name);",
    'require["bind"](null)(name);',
    'require["call"](null, name);',
    'require["apply"](null, [name]);',
    "Reflect.apply(require, null, [name]);",
    "Reflect.apply((require), null, [name]);",
    "Reflect.apply((0, require), null, [name]);",
    'Reflect["apply"](require, null, [name]);',
    'Reflect /* object */ . /* member */ apply(require, null, [name]);',
    "new globalThis.URL(name, import.meta.url);",
    'new globalThis /* object */ ["URL"](name, import.meta.url);',
    'globalThis["eval"]("require(name)");',
    'eval /* loader */ ("require(name)");',
    'Function /* loader */ ("return require")()(name);',
    'Function("return require")()(name);',
  ]) {
    await writeFile(entry, source);
    await assert.rejects(
      sourceGraphSHA256(root, [entry]),
      /aliased source loader is not lockable/,
    );
  }
});

export function modularValue() {
  return "modular-tool-ok";
}

import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import test from "node:test";

import {
  hostShellInvocation,
  killProcessTree,
  portableInvocation,
  resolveWindowsCommand,
} from "../dist/portable-process.js";
import { proxyBinaryCandidates } from "../dist/runtime.js";

test("Windows command shims launch their Node target without shell interpolation", () => {
  const root = mkdtempSync(join(tmpdir(), "caveman-agent-win-"));
  const bin = join(root, "bin");
  const pkg = join(root, "pkg");
  mkdirSync(bin);
  mkdirSync(pkg);
  const shim = join(bin, "caveman.CMD");
  const script = join(pkg, "cli.js");
  writeFileSync(shim, '@echo off\r\nendLocal & "%_prog%" "%dp0%\\..\\pkg\\cli.js" %*\r\n');
  writeFileSync(script, "");
  const env = { Path: bin, PATHEXT: ".EXE;.CMD" };
  assert.equal(resolveWindowsCommand("caveman", env), shim);
  assert.deepEqual(portableInvocation("caveman", ["x&y"], {
    platform: "win32",
    env,
    execPath: "node.exe",
  }), { command: "node.exe", args: [script, "x&y"] });
});

test("host shell selection is native on Windows and POSIX", () => {
  assert.deepEqual(hostShellInvocation("echo hi", "win32", { ComSpec: "C:\\Windows\\System32\\cmd.exe" }), {
    command: "C:\\Windows\\System32\\cmd.exe",
    args: ["/d", "/s", "/c", "echo hi"],
  });
  assert.deepEqual(hostShellInvocation("echo hi", "darwin", {}), {
    command: "/bin/sh",
    args: ["-c", "echo hi"],
  });
});

test("Windows process-tree cleanup uses taskkill and falls back on failure", () => {
  const calls = [];
  const child = { pid: 91, kill: () => calls.push("fallback") };
  killProcessTree(child, "SIGKILL", {
    platform: "win32",
    taskkill: (command, args, options) => {
      calls.push([command, args, options]);
      return { status: 0 };
    },
  });
  assert.deepEqual(calls, [[
    "taskkill.exe",
    ["/pid", "91", "/t", "/f"],
    { stdio: "ignore", windowsHide: true },
  ]]);
  killProcessTree(child, "SIGKILL", {
    platform: "win32",
    taskkill: () => ({ status: 1 }),
  });
  assert.equal(calls.at(-1), "fallback");
});

test("runtime probes use .exe companions from Windows Caveman home", () => {
  const home = resolve(tmpdir(), "caveman-agent-windows-home");
  assert.deepEqual(
    proxyBinaryCandidates("win32", home),
    [resolve(home, "bin", "caveman-proxy.exe"), "caveman-proxy.exe"],
  );
});

import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { resolve } from "node:path";
import test from "node:test";

import { createCodingAgent } from "../dist/code.js";

test("coding-agent host shell runs on current OS", async () => {
  const workspace = await mkdtemp(resolve(tmpdir(), "caveman-agent-shell-"));
  try {
    const codingAgent = createCodingAgent({ workspace, model: "anthropic/faux-1" });
    const shell = codingAgent.definition.tools.find((item) => item.name === "bash");
    const result = await shell.execute({ command: "echo caveman-portable-shell" });
    assert.match(String(result), /exit 0/);
    assert.match(String(result), /caveman-portable-shell/);
  } finally {
    await rm(workspace, { recursive: true, force: true });
  }
});

